return new {playing=UnityEditor.EditorApplication.isPlaying,scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>new{s.path,s.isDirty}).ToArray(),heroes=UnityEngine.Object.FindObjectsByType<UnityEngine.SkinnedMeshRenderer>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Where(r=>r.name=="Hero_TrouserLeg_1").Select(r=>new{r.name,scene=r.gameObject.scene.path,preview=UnityEditor.SceneManagement.EditorSceneManager.IsPreviewScene(r.gameObject.scene),root=r.transform.root.name,parents=r.GetComponentsInParent<UnityEngine.Transform>(true).Select(t=>t.name).ToArray(),components=r.transform.root.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true).Where(c=>c!=null).Select(c=>c.GetType().Name).Distinct().ToArray(),mesh=UnityEditor.AssetDatabase.GetAssetPath(r.sharedMesh),flags=r.hideFlags.ToString()}).ToArray()};
